<?php

declare(strict_types=1);

use Live627\PhpCsFixer\CustomFixers\PhpdocTagContinuationIndentFixer;
use PhpCsFixer\AbstractFixer;
use PhpCsFixer\Tests\Test\AbstractFixerTestCase;
use PHPUnit\Framework\Attributes\CoversClass;
use PHPUnit\Framework\Attributes\DataProvider;

/**
 * @internal
 *
 * @covers \Live627\PhpCsFixer\CustomFixers\PhpdocTagContinuationIndentFixer
 *
 * @extends AbstractFixerTestCase<\Live627\PhpCsFixer\CustomFixers\PhpdocTagContinuationIndentFixer>
 *
 * @phpstan-import-type _AutogeneratedInputConfiguration from PhpdocTagContinuationIndentFixer
 *
 * @author John Rayes <live627@gmail.com>
 *
 * @no-named-arguments Parameter names are not covered by the backward compatibility promise.
 */
#[CoversClass(PhpdocTagContinuationIndentFixer::class)]
final class PhpdocTagContinuationIndentFixerTest extends AbstractFixerTestCase
{
	/****************
	 * Public methods
	 ****************/

	/**
	 * @param _AutogeneratedInputConfiguration $configuration
	 */
	#[DataProvider('provideFixCases')]
	public function testFix(string $expected, ?string $input = null, ?array $configuration = null): void
	{
		if ($configuration !== null) {
			$this->fixer->configure($configuration);
		}

		$this->doTest($expected, $input);
	}

	/***********************
	 * Public static methods
	 ***********************/

	/**
	 * @return iterable<int, array{0: string, 1?: null|string, 2?: _AutogeneratedInputConfiguration}>
	 */
	public static function provideFixCases(): iterable
	{
		yield 'normalizes continuation indentation to default value' => [
			<<<'PHP'
				<?php
				/**
				 * @param string $name Description.
				 *    Continuation of the description.
				 *    Another continuation.
				 *
				 * @return string
				 *    Description of the return value.
				 */
				PHP,
			<<<'PHP'
				<?php
				/**
				 * @param string $name Description.
				 * Continuation of the description.
				 * Another continuation.
				 *
				 * @return string
				 * Description of the return value.
				 */
				PHP,
		];

		yield 'normalizes continuation indentation' => [
			<<<'PHP'
				<?php
				/**
				 * @param string $name Description.
				 *     Continuation of the description.
				 *     Another continuation.
				 *
				 * @return string
				 *     Description of the return value.
				 */
				PHP,
			<<<'PHP'
				<?php
				/**
				 * @param string $name Description.
				 * Continuation of the description.
				 * Another continuation.
				 *
				 * @return string
				 * Description of the return value.
				 */
				PHP,
			['indent' => 4],
		];

		yield 'normalizes continuation indentation to zero' => [
			<<<'PHP'
				<?php
				/**
				 * @param string $name Description.
				 * Continuation of the description.
				 * Another continuation.
				 *
				 * @return string
				 * Description of the return value.
				 */
				PHP,
			<<<'PHP'
				<?php
				/**
				 * @param string $name Description.
				 *     Continuation of the description.
				 *     Another continuation.
				 *
				 * @return string
				 *     Description of the return value.
				 */
				PHP,
			['indent' => 0],
		];

		yield 'preserves blank lines and tag lines' => [
			<<<'PHP'
				<?php
				/**
				 * @param string $name Description.
				 *     Continuation.
				 *
				 * @return string
				 *     Return description.
				 */
				PHP,
			<<<'PHP'
				<?php
				/**
				 * @param string $name Description.
				 *         Continuation.
				 *
				 * @return string
				 *       Return description.
				 */
				PHP,
			['indent' => 4],
		];

		yield 'does not change ordinary descriptions' => [
			<<<'PHP'
				<?php
				/**
				 * Ordinary summary.
				 *
				 * Ordinary description.
				 *     Its continuation.
				 */
				PHP,
		];

		yield 'preserves nested lists' => [
			<<<'PHP'
				<?php
				/**
				 * @param array $items Items:
				 *   - First item
				 *     - Nested item
				 *       - Deeper nested item
				 *   - Second item
				 */
				PHP,
			<<<'PHP'
				<?php
				/**
				 * @param array $items Items:
				 *     - First item
				 *       - Nested item
				 *         - Deeper nested item
				 *     - Second item
				 */
				PHP,
			['indent' => 2],
		];

		yield 'preserves indented code blocks' => [
			<<<'PHP'
				<?php
				/**
				 * @return array Example:
				 *   $items = [
				 *       'foo' => 'bar',
				 *       'baz' => 'qux',
				 *   ];
				 */
				PHP,
			<<<'PHP'
				<?php
				/**
				 * @return array Example:
				 *     $items = [
				 *         'foo' => 'bar',
				 *         'baz' => 'qux',
				 *     ];
				 */
				PHP,
			['indent' => 2],
		];

		yield 'normalizes the base while retaining relative indentation' => [
			<<<'PHP'
				<?php
				/**
				 * @param string $value Description.
				 *   First continuation.
				 *       Nested content.
				 *     Another continuation.
				 */
				PHP,
			<<<'PHP'
				<?php
				/**
				 * @param string $value Description.
				 *     First continuation.
				 *         Nested content.
				 *       Another continuation.
				 */
				PHP,
			['indent' => 2],
		];
	}

	/******************
	 * Internal methods
	 ******************/

	protected function createFixer(): AbstractFixer
	{
		return new PhpdocTagContinuationIndentFixer();
	}
}
